impl Order {
    pub fn total(&self) -> Money {
        if !self.is_valid() {
            return Money::ZERO;
        }
        self.discounted(self.subtotal())
    }

    fn is_valid(&self) -> bool { !self.lines.is_empty() }
    fn subtotal(&self) -> Money { self.lines.iter().map(Line::amount).sum() }
    fn discounted(&self, subtotal: Money) -> Money { subtotal - self.discount }
}
